 v_packet jsonb := $pkt${"checkpoint":"A6Q_C3","checks":[{"code":"NO_UNLICENSED_HOW","statement":"Los requisitos expresan QUÉ se exige, sin indicar CÓMO implementarlo: nada de tecnología, almacenamiento, interfaces técnicas ni diseño."},{"code":"NO_INVENTED_CONSTRAINTS","statement":"No se inventan permisos, estados, errores, efectos colaterales ni cifras: las dimensiones permissions, state, errors y side_effects quedan BLOCKED_UNDETERMINED con blocked_by no vacío."},{"code":"REQUIREMENTS_PROVISIONAL","statement":"Todo requisito es provisional (PROVISIONAL_PENDING_DECISION), depende de decisiones pendientes de la entrada y ninguna decisión pendiente queda sin cubrir ni se da por confirmada."}],"criterion":"Juicio independiente no encuentra obligación material omitida ni HOW impuesto","decision_doc":"docs/programming-agent/ANALYSIS_C3_TIER_ACCEPTANCE_DECISION_V1.md","evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"{\n  \"a5_stage_output\": {\n    \"current_decisions\": [],\n    \"current_decisions_basis\": \"La entrada A4 no contiene decisiones vigentes respaldadas por autoridad funcional. Sus referencias documentan el paquete de solicitud, el evento de traspaso y brechas no resueltas. No se puede considerar aprobada ninguna regla de producto a partir de estas fuentes.\",\n    \"decision_statement\": \"Se identifican cinco decisiones funcionales materiales pendientes sobre alcance del piloto, definición del ahorro, momento de comunicación, distinción respecto de la cuota y criterios de aceptación. Todas permanecen reservadas al propietario humano y ninguna ha sido aprobada por el agente. Antes de solicitar decisiones nuevas, corresponde contrastarlas con las reglas y decisiones vigentes, cuya autoridad no fue suministrada. La ausencia de fuentes no invalida decisiones existentes ni demuestra que todas requieran una nueva aprobación humana. La identificación de la implementación existente, la reconstrucción de la línea base AS-IS y la verificación de autoridad son actividades de investigación y no decisiones que deban trasladarse automáticamente al propietario. No se ha seleccionado ninguna alternativa funcional ni técnica, resuelto ningún ADR o autorizado implementación alguna.\",\n    \"decisions_approved_by_agent\": [],\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\",\n      \"gap:TARGET_IDENTITY_UNRESOLVED\",\n      \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"gap:IMPLEMENTATION_STATE_UNVERIFIED\",\n      \"gap:AS_IS_BASELINE_MISSING\",\n      \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n      \"impact:A4-DIRECT-001\",\n      \"impact:A4-DIRECT-002\",\n      \"impact:A4-DEPENDENCY-003\",\n      \"impact:A4-INDIRECT-001\",\n      \"impact:A4-INDIRECT-002\"\n    ],\n    \"no_self_approval\": true,\n    \"pending_decisions\": [\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-001\",\n        \"gap_ref\": \"TARGET_IDENTITY_UNRESOLVED\",\n        \"impact_ref\": \"A4-DIRECT-001\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué capacidad funcional, canales y segmentos de clientes deben quedar incluidos en el alcance del piloto para comunicar el ahorro antes de aceptar una oferta?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-002\",\n        \"gap_ref\": \"SAVINGS_SEMANTICS_UNRESOLVED\",\n        \"impact_ref\": \"A4-DIRECT-002\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué definición de ahorro y qué base de comparación deben utilizarse para comunicar al cliente el beneficio económico de negociar su deuda?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-003\",\n        \"gap_ref\": \"OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n        \"impact_ref\": \"A4-DEPENDENCY-003\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿En qué estado de la oferta y bajo qué condiciones debe estar disponible la información del ahorro antes de que el cliente acepte?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-004\",\n        \"gap_ref\": \"INSTALLMENT_DISTINCTION_UNRESOLVED\",\n        \"impact_ref\": \"A4-INDIRECT-001\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué distinción funcional debe establecerse entre el ahorro de la negociación y el monto de la cuota para evitar que el cliente confunda ambos conceptos?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-005\",\n        \"gap_ref\": \"ACCEPTANCE_EVIDENCE_MISSING\",\n        \"impact_ref\": \"A4-INDIRECT-002\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué criterios de aceptación deben utilizarse para determinar que los clientes comprenden el ahorro y no lo confunden con la cuota durante el piloto?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      }\n    ],\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"schema_version\": \"A5_DECISIONS_OUTPUT_V1\"\n  }\n}","input_origin":"A5Q_C2 GPT Native RAW (raw_output_sha256 8db2b41750ab425b85a5d1c6bbe336ee4ff75052c40e46c5101b9564936a09f1)","input_sha256":"960f333438d0799d95d237f91587302e7b8e973130a2ff65d0144a7eabbc6c7f","request_ref":"REQ-LF-A1Q-C2-PILOT-0001"},"items":[{"item_id":"ITEM_A","text":"{\n  \"schema_version\": \"A6_REQUIREMENTS_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"requirements\": [\n    {\n      \"requirement_id\": \"A6-REQ-001\",\n      \"type\": \"FUNCTIONAL\",\n      \"statement\": \"Los clientes comprendidos en el alcance autorizado del piloto deberán poder conocer el ahorro asociado a la negociación de su deuda antes de aceptar una oferta, conforme a las condiciones funcionales que se determinen.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-003\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-001\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-002\",\n      \"type\": \"DATA\",\n      \"statement\": \"La información del ahorro deberá corresponder a una definición y una base de comparación autorizadas, todavía pendientes de determinar.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-002\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-002\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-003\",\n      \"type\": \"FUNCTIONAL\",\n      \"statement\": \"La disponibilidad de la información del ahorro deberá respetar el momento y las condiciones autorizadas de la oferta antes de su aceptación.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-003\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-003\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-004\",\n      \"type\": \"FUNCTIONAL\",\n      \"statement\": \"La información comunicada al cliente deberá permitir distinguir el ahorro de la negociación del monto de la cuota, conforme a las definiciones funcionales que resulten autorizadas.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-004\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-005\",\n      \"type\": \"NON_FUNCTIONAL\",\n      \"statement\": \"La claridad de la información sobre ahorro y cuota deberá poder evaluarse mediante criterios de comprensión y aceptación previamente autorizados para el piloto.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-004\",\n        \"A5-DEC-005\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-005\"\n    }\n  ],\n  \"dimensions\": {\n    \"functional\": {\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"blocked_by\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-002\",\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"note\": \"Se identifican las obligaciones funcionales de comunicar el ahorro antes de aceptar una oferta y distinguirlo de la cuota. Su alcance, significado y condiciones permanecen pendientes de decisión.\"\n    },\n    \"data\": {\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"blocked_by\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],\n      \"note\": \"Se identifican como conceptos materiales el ahorro y el monto de la cuota. No están autorizadas sus definiciones, valores, bases de comparación ni relaciones. No se presuponen importes ni reglas de cálculo.\"\n    },\n    \"permissions\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",\n      \"blocked_by\": [\n        \"A5-DEC-001\"\n      ],\n      \"note\": \"La entrada no proporciona evidencia de permisos, roles autorizados ni reglas de acceso. No se establecen permisos por inferencia.\"\n    },\n    \"state\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",\n      \"blocked_by\": [\n        \"A5-DEC-003\"\n      ],\n      \"note\": \"No existe evidencia suficiente sobre los estados de la oferta, sus transiciones o las condiciones que habilitan comunicar el ahorro. No se inventan estados.\"\n    },\n    \"errors\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",\n      \"blocked_by\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-003\"\n      ],\n      \"note\": \"No se suministran comportamientos autorizados frente a información de ahorro no disponible, indeterminada o incompatible con las condiciones de la oferta. No se establecen resultados de error sin evidencia.\"\n    },\n    \"side_effects\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",\n      \"blocked_by\": [\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"note\": \"No se conocen efectos colaterales autorizados asociados a comunicar el ahorro, distinguir cuotas o aceptar ofertas. No se afirma que existan ni que estén ausentes.\"\n    }\n  },\n  \"evidence_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n    \"supabase://public.lf_eventos/20843\",\n    \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n    \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n    \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n    \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n    \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n    \"decision:A5-DEC-001\",\n    \"decision:A5-DEC-002\",\n    \"decision:A5-DEC-003\",\n    \"decision:A5-DEC-004\",\n    \"decision:A5-DEC-005\"\n  ],\n  \"no_unlicensed_how\": true,\n  \"requirements_statement\": \"Se formularon cinco requisitos provisionales, de naturaleza funcional, de datos y no funcional, vinculados a las cinco decisiones pendientes de A5. Ninguno constituye una obligación aprobada ni una autorización de implementación. Las dimensiones funcional y de datos contienen únicamente necesidades condicionadas. Permisos, estados, errores y efectos colaterales permanecen BLOCKED_UNDETERMINED por falta de evidencia. También están pendientes la verificación de autoridad vigente, la identificación de la implementación existente y la línea base AS-IS. El resultado expresa exclusivamente QUÉ se necesita definir y cumplir, sin seleccionar tecnología, diseño, estructuras internas, reglas económicas no autorizadas ni decisiones de producto.\"\n}"},{"item_id":"ITEM_B","text":"{\n  \"schema_version\": \"A6_REQUIREMENTS_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"requirements\": [\n    {\n      \"requirement_id\": \"A6-REQ-001\",\n      \"type\": \"FUNCTIONAL\",\n      \"statement\": \"Los clientes comprendidos en el alcance autorizado del piloto deberán poder conocer el ahorro asociado a la negociación de su deuda antes de aceptar una oferta, conforme a las condiciones funcionales que se determinen.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-003\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-001\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-002\",\n      \"type\": \"DATA\",\n      \"statement\": \"La información del ahorro deberá almacenarse en una tabla de la base de datos y exponerse mediante un endpoint API.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-002\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-002\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-003\",\n      \"type\": \"FUNCTIONAL\",\n      \"statement\": \"La disponibilidad de la información del ahorro deberá respetar el momento y las condiciones autorizadas de la oferta antes de su aceptación.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-003\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-003\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-004\",\n      \"type\": \"FUNCTIONAL\",\n      \"statement\": \"La información comunicada al cliente deberá permitir distinguir el ahorro de la negociación del monto de la cuota, conforme a las definiciones funcionales que resulten autorizadas.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-004\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-005\",\n      \"type\": \"NON_FUNCTIONAL\",\n      \"statement\": \"La claridad de la información sobre ahorro y cuota deberá poder evaluarse mediante criterios de comprensión y aceptación previamente autorizados para el piloto.\",\n      \"status\": \"CONFIRMED\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-004\",\n        \"A5-DEC-005\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-005\"\n    }\n  ],\n  \"dimensions\": {\n    \"functional\": {\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"blocked_by\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-002\",\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"note\": \"Se identifican las obligaciones funcionales de comunicar el ahorro antes de aceptar una oferta y distinguirlo de la cuota. Su alcance, significado y condiciones permanecen pendientes de decisión.\"\n    },\n    \"data\": {\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"blocked_by\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],\n      \"note\": \"Se identifican como conceptos materiales el ahorro y el monto de la cuota. No están autorizadas sus definiciones, valores, bases de comparación ni relaciones. No se presuponen importes ni reglas de cálculo.\"\n    },\n    \"permissions\": {\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"blocked_by\": [\n        \"A5-DEC-001\"\n      ],\n      \"note\": \"La entrada no proporciona evidencia de permisos, roles autorizados ni reglas de acceso. No se establecen permisos por inferencia.\"\n    },\n    \"state\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",\n      \"blocked_by\": [\n        \"A5-DEC-003\"\n      ],\n      \"note\": \"No existe evidencia suficiente sobre los estados de la oferta, sus transiciones o las condiciones que habilitan comunicar el ahorro. No se inventan estados.\"\n    },\n    \"errors\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",\n      \"blocked_by\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-003\"\n      ],\n      \"note\": \"No se suministran comportamientos autorizados frente a información de ahorro no disponible, indeterminada o incompatible con las condiciones de la oferta. No se establecen resultados de error sin evidencia.\"\n    },\n    \"side_effects\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",\n      \"blocked_by\": [\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"note\": \"No se conocen efectos colaterales autorizados asociados a comunicar el ahorro, distinguir cuotas o aceptar ofertas. No se afirma que existan ni que estén ausentes.\"\n    }\n  },\n  \"evidence_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n    \"supabase://public.lf_eventos/20843\",\n    \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n    \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n    \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n    \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n    \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n    \"decision:A5-DEC-001\",\n    \"decision:A5-DEC-002\",\n    \"decision:A5-DEC-003\",\n    \"decision:A5-DEC-004\",\n    \"decision:A5-DEC-005\"\n  ],\n  \"no_unlicensed_how\": true,\n  \"requirements_statement\": \"Se formularon cinco requisitos provisionales, de naturaleza funcional, de datos y no funcional, vinculados a las cinco decisiones pendientes de A5. Ninguno constituye una obligación aprobada ni una autorización de implementación. Las dimensiones funcional y de datos contienen únicamente necesidades condicionadas. Permisos, estados, errores y efectos colaterales permanecen BLOCKED_UNDETERMINED por falta de evidencia. También están pendientes la verificación de autoridad vigente, la identificación de la implementación existente y la línea base AS-IS. El resultado expresa exclusivamente QUÉ se necesita definir y cumplir, sin seleccionar tecnología, diseño, estructuras internas, reglas económicas no autorizadas ni decisiones de producto.\"\n}"}],"limits":{"independent_review":false,"provider_attested":false,"real_execution_receipt":false},"packet_sha256":"ae5282446901f2884a63250798149aa48e5f5194837eb3df0a4dd343b33313c9","prompt_for_gpt":"Eres un revisor independiente. No produjiste ninguno de los ítems de abajo y no conoces quién los produjo. Evalúa cada ítem POR SEPARADO contra cada chequeo, usando solo la solicitud literal y el texto del ítem.\n\nCRITERIO: Juicio independiente no encuentra obligación material omitida ni HOW impuesto\n\nCHEQUEOS (evalúa cada uno, PASS o FAIL):\n- NO_UNLICENSED_HOW: Los requisitos expresan QUÉ se exige, sin indicar CÓMO implementarlo: nada de tecnología, almacenamiento, interfaces técnicas ni diseño.\n- NO_INVENTED_CONSTRAINTS: No se inventan permisos, estados, errores, efectos colaterales ni cifras: las dimensiones permissions, state, errors y side_effects quedan BLOCKED_UNDETERMINED con blocked_by no vacío.\n- REQUIREMENTS_PROVISIONAL: Todo requisito es provisional (PROVISIONAL_PENDING_DECISION), depende de decisiones pendientes de la entrada y ninguna decisión pendiente queda sin cubrir ni se da por confirmada.\n\nREGLAS DE LA ETAPA (con las que se produjo el ítem; úsalas solo para juzgar, no para producir nada):\nExpresa QUÉ debe cumplir el cambio, sin indicar CÓMO implementarlo (nada de tecnología, almacenamiento, interfaces técnicas ni diseño). Toda decisión de A5 sigue pendiente, así que ningún requisito puede darse por confirmado: cada requisito es provisional y depende de decisiones pendientes. No inventes permisos, estados, errores, efectos colaterales ni cifras: si la entrada no los respalda, declara esa dimensión como bloqueada. Referencias válidas: las evidence_refs de la entrada y 'decision:<decision_id>' para cada decisión pendiente. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, requirements, dimensions, evidence_refs, no_unlicensed_how, requirements_statement. schema_version='A6_REQUIREMENTS_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. requirements: lista de {requirement_id (único), type (FUNCTIONAL|DATA|NON_FUNCTIONAL), statement (qué se exige, texto, sin cifras que no estén en la entrada), status='PROVISIONAL_PENDING_DECISION', depends_on_decisions (lista no vacía de decision_id de la entrada), source_ref (una referencia válida)}; deben depender en conjunto de al menos 4 decisiones distintas y al menos uno debe ser FUNCTIONAL. dimensions: objeto con exactamente las claves functional, data, permissions, state, errors, side_effects; cada una es {status ('PROVISIONAL_PENDING_DECISION' o 'BLOCKED_UNDETERMINED'), blocked_by (lista de decision_id de la entrada), note (texto)}. permissions, state, errors y side_effects deben ser 'BLOCKED_UNDETERMINED' con blocked_by no vacío. evidence_refs: lista no vacía de referencias válidas. no_unlicensed_how=true. requirements_statement: texto que explica qué quedó especificado y qué sigue bloqueado.\n\nSOLICITUD LITERAL (entrada):\n{\n  \"a5_stage_output\": {\n    \"current_decisions\": [],\n    \"current_decisions_basis\": \"La entrada A4 no contiene decisiones vigentes respaldadas por autoridad funcional. Sus referencias documentan el paquete de solicitud, el evento de traspaso y brechas no resueltas. No se puede considerar aprobada ninguna regla de producto a partir de estas fuentes.\",\n    \"decision_statement\": \"Se identifican cinco decisiones funcionales materiales pendientes sobre alcance del piloto, definición del ahorro, momento de comunicación, distinción respecto de la cuota y criterios de aceptación. Todas permanecen reservadas al propietario humano y ninguna ha sido aprobada por el agente. Antes de solicitar decisiones nuevas, corresponde contrastarlas con las reglas y decisiones vigentes, cuya autoridad no fue suministrada. La ausencia de fuentes no invalida decisiones existentes ni demuestra que todas requieran una nueva aprobación humana. La identificación de la implementación existente, la reconstrucción de la línea base AS-IS y la verificación de autoridad son actividades de investigación y no decisiones que deban trasladarse automáticamente al propietario. No se ha seleccionado ninguna alternativa funcional ni técnica, resuelto ningún ADR o autorizado implementación alguna.\",\n    \"decisions_approved_by_agent\": [],\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\",\n      \"gap:TARGET_IDENTITY_UNRESOLVED\",\n      \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"gap:IMPLEMENTATION_STATE_UNVERIFIED\",\n      \"gap:AS_IS_BASELINE_MISSING\",\n      \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n      \"impact:A4-DIRECT-001\",\n      \"impact:A4-DIRECT-002\",\n      \"impact:A4-DEPENDENCY-003\",\n      \"impact:A4-INDIRECT-001\",\n      \"impact:A4-INDIRECT-002\"\n    ],\n    \"no_self_approval\": true,\n    \"pending_decisions\": [\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-001\",\n        \"gap_ref\": \"TARGET_IDENTITY_UNRESOLVED\",\n        \"impact_ref\": \"A4-DIRECT-001\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué capacidad funcional, canales y segmentos de clientes deben quedar incluidos en el alcance del piloto para comunicar el ahorro antes de aceptar una oferta?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-002\",\n        \"gap_ref\": \"SAVINGS_SEMANTICS_UNRESOLVED\",\n        \"impact_ref\": \"A4-DIRECT-002\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué definición de ahorro y qué base de comparación deben utilizarse para comunicar al cliente el beneficio económico de negociar su deuda?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-003\",\n        \"gap_ref\": \"OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n        \"impact_ref\": \"A4-DEPENDENCY-003\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿En qué estado de la oferta y bajo qué condiciones debe estar disponible la información del ahorro antes de que el cliente acepte?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-004\",\n        \"gap_ref\": \"INSTALLMENT_DISTINCTION_UNRESOLVED\",\n        \"impact_ref\": \"A4-INDIRECT-001\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué distinción funcional debe establecerse entre el ahorro de la negociación y el monto de la cuota para evitar que el cliente confunda ambos conceptos?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      },\n      {\n        \"blocking\": true,\n        \"decision_id\": \"A5-DEC-005\",\n        \"gap_ref\": \"ACCEPTANCE_EVIDENCE_MISSING\",\n        \"impact_ref\": \"A4-INDIRECT-002\",\n        \"owner_role\": \"OWNER_HUMAN\",\n        \"question\": \"¿Qué criterios de aceptación deben utilizarse para determinar que los clientes comprenden el ahorro y no lo confunden con la cuota durante el piloto?\",\n        \"status\": \"PENDING_OWNER_DECISION\"\n      }\n    ],\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"schema_version\": \"A5_DECISIONS_OUTPUT_V1\"\n  }\n}\n\n<<<ITEM_A>>>\n{\n  \"schema_version\": \"A6_REQUIREMENTS_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"requirements\": [\n    {\n      \"requirement_id\": \"A6-REQ-001\",\n      \"type\": \"FUNCTIONAL\",\n      \"statement\": \"Los clientes comprendidos en el alcance autorizado del piloto deberán poder conocer el ahorro asociado a la negociación de su deuda antes de aceptar una oferta, conforme a las condiciones funcionales que se determinen.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-003\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-001\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-002\",\n      \"type\": \"DATA\",\n      \"statement\": \"La información del ahorro deberá corresponder a una definición y una base de comparación autorizadas, todavía pendientes de determinar.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-002\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-002\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-003\",\n      \"type\": \"FUNCTIONAL\",\n      \"statement\": \"La disponibilidad de la información del ahorro deberá respetar el momento y las condiciones autorizadas de la oferta antes de su aceptación.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-003\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-003\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-004\",\n      \"type\": \"FUNCTIONAL\",\n      \"statement\": \"La información comunicada al cliente deberá permitir distinguir el ahorro de la negociación del monto de la cuota, conforme a las definiciones funcionales que resulten autorizadas.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-004\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-005\",\n      \"type\": \"NON_FUNCTIONAL\",\n      \"statement\": \"La claridad de la información sobre ahorro y cuota deberá poder evaluarse mediante criterios de comprensión y aceptación previamente autorizados para el piloto.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-004\",\n        \"A5-DEC-005\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-005\"\n    }\n  ],\n  \"dimensions\": {\n    \"functional\": {\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"blocked_by\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-002\",\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"note\": \"Se identifican las obligaciones funcionales de comunicar el ahorro antes de aceptar una oferta y distinguirlo de la cuota. Su alcance, significado y condiciones permanecen pendientes de decisión.\"\n    },\n    \"data\": {\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"blocked_by\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],\n      \"note\": \"Se identifican como conceptos materiales el ahorro y el monto de la cuota. No están autorizadas sus definiciones, valores, bases de comparación ni relaciones. No se presuponen importes ni reglas de cálculo.\"\n    },\n    \"permissions\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",\n      \"blocked_by\": [\n        \"A5-DEC-001\"\n      ],\n      \"note\": \"La entrada no proporciona evidencia de permisos, roles autorizados ni reglas de acceso. No se establecen permisos por inferencia.\"\n    },\n    \"state\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",\n      \"blocked_by\": [\n        \"A5-DEC-003\"\n      ],\n      \"note\": \"No existe evidencia suficiente sobre los estados de la oferta, sus transiciones o las condiciones que habilitan comunicar el ahorro. No se inventan estados.\"\n    },\n    \"errors\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",\n      \"blocked_by\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-003\"\n      ],\n      \"note\": \"No se suministran comportamientos autorizados frente a información de ahorro no disponible, indeterminada o incompatible con las condiciones de la oferta. No se establecen resultados de error sin evidencia.\"\n    },\n    \"side_effects\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",\n      \"blocked_by\": [\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"note\": \"No se conocen efectos colaterales autorizados asociados a comunicar el ahorro, distinguir cuotas o aceptar ofertas. No se afirma que existan ni que estén ausentes.\"\n    }\n  },\n  \"evidence_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n    \"supabase://public.lf_eventos/20843\",\n    \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n    \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n    \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n    \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n    \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n    \"decision:A5-DEC-001\",\n    \"decision:A5-DEC-002\",\n    \"decision:A5-DEC-003\",\n    \"decision:A5-DEC-004\",\n    \"decision:A5-DEC-005\"\n  ],\n  \"no_unlicensed_how\": true,\n  \"requirements_statement\": \"Se formularon cinco requisitos provisionales, de naturaleza funcional, de datos y no funcional, vinculados a las cinco decisiones pendientes de A5. Ninguno constituye una obligación aprobada ni una autorización de implementación. Las dimensiones funcional y de datos contienen únicamente necesidades condicionadas. Permisos, estados, errores y efectos colaterales permanecen BLOCKED_UNDETERMINED por falta de evidencia. También están pendientes la verificación de autoridad vigente, la identificación de la implementación existente y la línea base AS-IS. El resultado expresa exclusivamente QUÉ se necesita definir y cumplir, sin seleccionar tecnología, diseño, estructuras internas, reglas económicas no autorizadas ni decisiones de producto.\"\n}\n<<<FIN ITEM_A>>>\n\n<<<ITEM_B>>>\n{\n  \"schema_version\": \"A6_REQUIREMENTS_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"requirements\": [\n    {\n      \"requirement_id\": \"A6-REQ-001\",\n      \"type\": \"FUNCTIONAL\",\n      \"statement\": \"Los clientes comprendidos en el alcance autorizado del piloto deberán poder conocer el ahorro asociado a la negociación de su deuda antes de aceptar una oferta, conforme a las condiciones funcionales que se determinen.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-003\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-001\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-002\",\n      \"type\": \"DATA\",\n      \"statement\": \"La información del ahorro deberá almacenarse en una tabla de la base de datos y exponerse mediante un endpoint API.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-002\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-002\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-003\",\n      \"type\": \"FUNCTIONAL\",\n      \"statement\": \"La disponibilidad de la información del ahorro deberá respetar el momento y las condiciones autorizadas de la oferta antes de su aceptación.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-003\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-003\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-004\",\n      \"type\": \"FUNCTIONAL\",\n      \"statement\": \"La información comunicada al cliente deberá permitir distinguir el ahorro de la negociación del monto de la cuota, conforme a las definiciones funcionales que resulten autorizadas.\",\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-004\"\n    },\n    {\n      \"requirement_id\": \"A6-REQ-005\",\n      \"type\": \"NON_FUNCTIONAL\",\n      \"statement\": \"La claridad de la información sobre ahorro y cuota deberá poder evaluarse mediante criterios de comprensión y aceptación previamente autorizados para el piloto.\",\n      \"status\": \"CONFIRMED\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-004\",\n        \"A5-DEC-005\"\n      ],\n      \"source_ref\": \"decision:A5-DEC-005\"\n    }\n  ],\n  \"dimensions\": {\n    \"functional\": {\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"blocked_by\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-002\",\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"note\": \"Se identifican las obligaciones funcionales de comunicar el ahorro antes de aceptar una oferta y distinguirlo de la cuota. Su alcance, significado y condiciones permanecen pendientes de decisión.\"\n    },\n    \"data\": {\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"blocked_by\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],\n      \"note\": \"Se identifican como conceptos materiales el ahorro y el monto de la cuota. No están autorizadas sus definiciones, valores, bases de comparación ni relaciones. No se presuponen importes ni reglas de cálculo.\"\n    },\n    \"permissions\": {\n      \"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"blocked_by\": [\n        \"A5-DEC-001\"\n      ],\n      \"note\": \"La entrada no proporciona evidencia de permisos, roles autorizados ni reglas de acceso. No se establecen permisos por inferencia.\"\n    },\n    \"state\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",\n      \"blocked_by\": [\n        \"A5-DEC-003\"\n      ],\n      \"note\": \"No existe evidencia suficiente sobre los estados de la oferta, sus transiciones o las condiciones que habilitan comunicar el ahorro. No se inventan estados.\"\n    },\n    \"errors\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",\n      \"blocked_by\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-003\"\n      ],\n      \"note\": \"No se suministran comportamientos autorizados frente a información de ahorro no disponible, indeterminada o incompatible con las condiciones de la oferta. No se establecen resultados de error sin evidencia.\"\n    },\n    \"side_effects\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",\n      \"blocked_by\": [\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"note\": \"No se conocen efectos colaterales autorizados asociados a comunicar el ahorro, distinguir cuotas o aceptar ofertas. No se afirma que existan ni que estén ausentes.\"\n    }\n  },\n  \"evidence_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n    \"supabase://public.lf_eventos/20843\",\n    \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n    \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n    \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n    \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n    \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n    \"decision:A5-DEC-001\",\n    \"decision:A5-DEC-002\",\n    \"decision:A5-DEC-003\",\n    \"decision:A5-DEC-004\",\n    \"decision:A5-DEC-005\"\n  ],\n  \"no_unlicensed_how\": true,\n  \"requirements_statement\": \"Se formularon cinco requisitos provisionales, de naturaleza funcional, de datos y no funcional, vinculados a las cinco decisiones pendientes de A5. Ninguno constituye una obligación aprobada ni una autorización de implementación. Las dimensiones funcional y de datos contienen únicamente necesidades condicionadas. Permisos, estados, errores y efectos colaterales permanecen BLOCKED_UNDETERMINED por falta de evidencia. También están pendientes la verificación de autoridad vigente, la identificación de la implementación existente y la línea base AS-IS. El resultado expresa exclusivamente QUÉ se necesita definir y cumplir, sin seleccionar tecnología, diseño, estructuras internas, reglas económicas no autorizadas ni decisiones de producto.\"\n}\n<<<FIN ITEM_B>>>\n\nResponde SOLO con un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version ('ANALYSIS_GPT_NATIVE_BLIND_REVIEW_V1'), unit ('A6Q'), items. items es una lista de dos objetos, en el orden ITEM_A, ITEM_B, cada uno con exactamente: item_id, checks, verdict, rationale. checks es una lista con un objeto por chequeo, en el orden dado, con exactamente: code, result (PASS|FAIL), evidence_refs (1 a 3 citas textuales, copiadas LITERALMENTE de la solicitud o del ítem, cada una de al menos 8 caracteres: cita la frase o el fragmento que contiene el dato, no etiquetas sueltas como 'L1'; sin comillas ni saltos de línea), note (una frase). verdict es PASS solo si los tres chequeos son PASS; si no, FAIL. rationale: 1 a 3 frases. No asumas que un ítem es correcto o incorrecto por su posición.","rules_text":"Expresa QUÉ debe cumplir el cambio, sin indicar CÓMO implementarlo (nada de tecnología, almacenamiento, interfaces técnicas ni diseño). Toda decisión de A5 sigue pendiente, así que ningún requisito puede darse por confirmado: cada requisito es provisional y depende de decisiones pendientes. No inventes permisos, estados, errores, efectos colaterales ni cifras: si la entrada no los respalda, declara esa dimensión como bloqueada. Referencias válidas: las evidence_refs de la entrada y 'decision:<decision_id>' para cada decisión pendiente. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, requirements, dimensions, evidence_refs, no_unlicensed_how, requirements_statement. schema_version='A6_REQUIREMENTS_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. requirements: lista de {requirement_id (único), type (FUNCTIONAL|DATA|NON_FUNCTIONAL), statement (qué se exige, texto, sin cifras que no estén en la entrada), status='PROVISIONAL_PENDING_DECISION', depends_on_decisions (lista no vacía de decision_id de la entrada), source_ref (una referencia válida)}; deben depender en conjunto de al menos 4 decisiones distintas y al menos uno debe ser FUNCTIONAL. dimensions: objeto con exactamente las claves functional, data, permissions, state, errors, side_effects; cada una es {status ('PROVISIONAL_PENDING_DECISION' o 'BLOCKED_UNDETERMINED'), blocked_by (lista de decision_id de la entrada), note (texto)}. permissions, state, errors y side_effects deben ser 'BLOCKED_UNDETERMINED' con blocked_by no vacío. evidence_refs: lista no vacía de referencias válidas. no_unlicensed_how=true. requirements_statement: texto que explica qué quedó especificado y qué sigue bloqueado.","schema":"ANALYSIS_GPT_NATIVE_C3_PACKET_V1","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A6Q/A6Q_C3","unit":"A6"}$pkt$;
 v_key jsonb := $key${"c2_chat_transcript_ref":"https://chatgpt.com/g/g-p-6a6d99aa6330819180764b10e86c9392-agente-de-programacion/c/6acef59c-df30-83e8-accd-609d3b78e0bf","c2_raw_output_sha256":"e6ceef2605a44a7f63837784089cf3c8f40f7a3500d20f2a07adfc63c5cfac29","decoy_item_id":"ITEM_B","decoy_must_fail_checks":["NO_UNLICENSED_HOW","REQUIREMENTS_PROVISIONAL"],"decoy_sha256":"0ce28180e984404b056b8e91567551ba735f861c22de21cd6ea43076959a8f96","real_item_id":"ITEM_A","replacements":[["La información del ahorro deberá corresponder a una definición y una base de comparación autorizadas, todavía pendientes de determinar.","La información del ahorro deberá almacenarse en una tabla de la base de datos y exponerse mediante un endpoint API."],["\"permissions\": {\n      \"status\": \"BLOCKED_UNDETERMINED\",","\"permissions\": {\n      \"status\": \"PROVISIONAL_PENDING_DECISION\","],["\"status\": \"PROVISIONAL_PENDING_DECISION\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-004\",\n        \"A5-DEC-005\"","\"status\": \"CONFIRMED\",\n      \"depends_on_decisions\": [\n        \"A5-DEC-004\",\n        \"A5-DEC-005\""]]}$key$;
 v_m jsonb; v_cap jsonb; v_raw text; v_decoy text; v_old text; v_new text; v_e jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp OR v_packet->>'packet_sha256' <> v_packet_sha THEN RAISE EXCEPTION 'A6Q_C3_PACKET_IDENTITY'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,independent_review}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A6Q_C3_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_c2) IS DISTINCT FROM 'DONE'
    OR (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A6Q_C3_STATE'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A6Q_UNIT_NOT_FOUND'; END IF;
 v_cap := v_m#>'{gpt_native_captures_v1,A6Q_C2}';
 IF v_cap IS NULL OR encode(sha256(convert_to(v_cap->>'raw_output_text','UTF8')),'hex') <> v_cap->>'raw_output_sha256'
    OR v_cap->>'raw_output_sha256' <> v_key->>'c2_raw_output_sha256' OR v_cap->>'chat_transcript_ref' <> v_key->>'c2_chat_transcript_ref'
  THEN RAISE EXCEPTION 'A6Q_C3_C2_CAPTURE_BINDING'; END IF;
 IF v_packet->'input' IS DISTINCT FROM (v_m#>'{gpt_native_packets_v1,A6Q_C2,input}') THEN RAISE EXCEPTION 'A6Q_C3_INPUT_NOT_C2_INPUT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_m#>>'{gpt_native_packets_v1,A6Q_C2,prompt_for_gpt}'))=0 THEN RAISE EXCEPTION 'A6Q_C3_RULES_NOT_FROM_C2_PROMPT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_packet->>'prompt_for_gpt'))=0 THEN RAISE EXCEPTION 'A6Q_C3_RULES_NOT_IN_PROMPT'; END IF;
 v_raw := v_cap->>'raw_output_text'; v_decoy := v_raw;
 FOR v_e IN SELECT * FROM jsonb_array_elements(v_key->'replacements') LOOP
  v_old := v_e->>0; v_new := v_e->>1;
  IF (length(v_raw)-length(replace(v_raw,v_old,'')))<>length(v_old) THEN RAISE EXCEPTION 'A6Q_C3_DECOY_REPLACEMENT_NOT_UNIQUE'; END IF;
  v_decoy := replace(v_decoy,v_old,v_new);
 END LOOP;
 IF v_decoy = v_raw OR encode(sha256(convert_to(v_decoy,'UTF8')),'hex') <> v_key->>'decoy_sha256' THEN RAISE EXCEPTION 'A6Q_C3_DECOY_MISMATCH'; END IF;
 PERFORM v_decoy::jsonb;
 IF (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'real_item_id') IS DISTINCT FROM v_raw
    OR (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'decoy_item_id') IS DISTINCT FROM v_decoy
    OR jsonb_array_length(v_packet->'items')<>2 THEN RAISE EXCEPTION 'A6Q_C3_ITEMS_NOT_FROM_C2'; END IF;
 IF position(v_cap->>'chat_transcript_ref' in v_packet->>'prompt_for_gpt')>0 OR position('DECOY' in v_packet::text)>0 OR position('REAL' in v_packet->>'prompt_for_gpt')>0
  THEN RAISE EXCEPTION 'A6Q_C3_PACKET_NOT_BLIND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A6Q_C3}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A6Q_C3,packet_sha256}' <> v_packet_sha
    AND NOT (v_key->>'supersedes_packet_sha256' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A6Q_C3,packet_sha256}' = v_key->>'supersedes_packet_sha256' AND v_m#>'{gpt_native_captures_v1,A6Q_C3}' IS NULL)
  THEN RAISE EXCEPTION 'A6Q_C3_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units SET unit_metadata = v_m
   || jsonb_build_object('gpt_native_packets_v1', COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A6Q_C3',v_packet))
   || jsonb_build_object('gpt_native_c3_keys_v1', COALESCE(v_m->'gpt_native_c3_keys_v1','{}'::jsonb) || jsonb_build_object('A6Q_C3',v_key))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 IF v_m#>'{gpt_native_packets_v1,A6Q_C3}' IS DISTINCT FROM v_packet OR v_m#>'{gpt_native_c3_keys_v1,A6Q_C3}' IS DISTINCT FROM v_key THEN RAISE EXCEPTION 'A6Q_C3_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A6Q_C3_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A6Q_C3.GPT_NATIVE_HANDOFF',
   'Blinded A6Q_C3 review packet handed to a separate GPT Native chat; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object('evidence_schema_version','operational-event/v2','execution_id',v_exec,'producer','ANALYSIS_QUAL_C3_GPT_HANDOFF_V1',
    'purpose','Hand the blinded A6Q_C3 review packet to GPT Native in a chat separate from the C2 producer chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_sha256',v_packet_sha,'producer_mode','GPT_NATIVE_REVIEW','evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'separate_chat_required',true,'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in this NEW chat with ONLY the JSON object, unedited. Do not use the C2 producer chat. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent for C3. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured review is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt' THEN RAISE EXCEPTION 'A6Q_C3_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A6Q_C3_CHECKPOINTS_CHANGED'; END IF;
END
$a6q_c3_prep$;
COMMIT;
